local OverseaManageCafeRoleListRoot = Class('OverseaManageCafeRoleListRoot')
local MaidCoffeeConstants = import("Game.MaidCoffee.MaidCoffeeConstants")
local MaidCoffeeUtils     = import("Game.MaidCoffee.MaidCoffeeUtils")
local component = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
local ReportDescPath = "Game.MaidCoffee.MaidCoffeeUIDialog.Cell.OSManegeReportDescriptionCell"
local ClerkCount = 3
function OverseaManageCafeRoleListRoot:__init()
    self.manageEnv = nil
    self.clerkEnv = nil
end

function OverseaManageCafeRoleListRoot:__delete()
    self.manageEnv = nil
    self.clerkEnv = nil
end

function OverseaManageCafeRoleListRoot:Awake()
    self:InitNodeEnv()
end

function OverseaManageCafeRoleListRoot:InitNodeEnv()
    if self.ManageDescCell then
        local env = CfUtils.GetLuaScr(self.ManageDescCell,ReportDescPath)
        if env then
            self.manageEnv = env
        end
    end

    self.clerkEnv = {}
    for i = 1, ClerkCount do
        local node = self["ClerkDescCell"..i]
        if node then
            local env = CfUtils.GetLuaScr(node,ReportDescPath)
            if env then
                self.clerkEnv[i] = env
            end
        end
    end
end

function OverseaManageCafeRoleListRoot:RefreshShow()
    self:RefreshManageShow()
    self:RefreshClerkShow()
end

function OverseaManageCafeRoleListRoot:RefreshManageShow()
    local manageId = component:GetStaffInfoByType(MaidCoffeeConstants.SelectType.Manager ,1)
    local isHaveOwner = (tonumber(manageId) ~= 0)

    KTool.SetActive(self.ManageEmpty,not isHaveOwner)
    KTool.SetActive(self.ManageDescCell, isHaveOwner)

    local state = isHaveOwner and 2 or 1
    CfUtils.SetUISwitchImage(self.ManageImgBg,state)
    CfUtils.SetUISwitchText(self.ManageDesc,state)
    if isHaveOwner then
        self.manageEnv:RefreshPersonShow(manageId)
    end
end

function OverseaManageCafeRoleListRoot:RefreshClerkShow()
    local isHaveClerk = false
    for i = 1, ClerkCount do
        local clerkId = component:GetStaffInfoByType(MaidCoffeeConstants.SelectType.Clerk ,i)
        KTool.SetActive(self.clerkEnv[i].controller.gameObject,clerkId > 0)
        if clerkId > 0 then
            isHaveClerk = true
            self.clerkEnv[i]:RefreshPersonShow(clerkId)
        end
    end
    KTool.SetActive(self.ClerkEmpty,not isHaveClerk)
    local state = isHaveClerk and 2 or 1
    CfUtils.SetUISwitchImage(self.ClerkImgBg,state)
    CfUtils.SetUISwitchText(self.ClerkDesc,state)
end

function OverseaManageCafeRoleListRoot:Start()
end

function OverseaManageCafeRoleListRoot:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
end

